-- reproducible from a fresh database.

insert into public.capability_registry (
  capability_key, name, description, category, department,
  agent_tool_name, read_write, tenant_scope, cost_profile, risk, verification_method,
  status, status_notes, last_verified_at, last_verified_by
) values (
  'capability:connector_capability_control_plane',
  'Admin Connector/Capability Control Plane -- master brief Section 25-32, the next major admin feature',
  'A real, code-complete platform-and-company-scoped governance layer for external capabilities Hermes'' own execution can use: AWS, GitHub, Supabase, Vercel, WhatsApp, Meta, Google Workspace, Gemini, OpenRouter, and browser/computer (the exact 10 named in the master brief). New package @stratxcel/connectors (types/registry/repository/health). Investigated the repo thoroughly BEFORE building (per Section 46) and found three real, existing, narrower systems that must never be duplicated: tenant_provider_connections (@stratxcel/byok, tenant BYOK AI-key billing), search_website_connections (@stratxcel/search-discovery, a tenant''s own Vercel token for their website), search_google_connections (a tenant''s own Google OAuth for GSC/GA4), and owner_source_connections (lib/owner-brain, the Founder''s PERSONAL data-ingestion sources) -- none of these is a Hermes-execution capability governance layer, so this is a genuine new layer, not a duplicate. For every connector whose real connection already exists elsewhere (vercel company-scope, whatsapp, meta, google_workspace), this control plane is a READ-ONLY adapter over the existing table -- it never re-stores a credential that already lives somewhere real. For platform-level connectors with no existing store (aws/github/supabase/gemini/openrouter/browser), it uses @stratxcel/byok''s real, already-live AES-256-GCM vault (vault_secrets) unmodified -- never a second encryption implementation. Health is computed for real per connector: aws reuses @stratxcel/queue''s getWorkerHealth against real worker_heartbeats; gemini/openrouter reuse @stratxcel/ai-runtime''s already-live probeGeminiReadiness/probeOpenRouterReadiness; vercel (platform) reuses validateVercelToken; github does a real live GET https://api.github.com/user; whatsapp/meta read real phone_bindings; google_workspace reads real search_google_connections; supabase is honestly presence-based only (no live Management API probe in v1, stated explicitly rather than fabricated); browser is honestly always pending (no real Hermes browser tool exists yet). A real, functional (not decorative) Admin UI at /admin/connectors lets staff CONNECT/DISCONNECT a connector, VIEW its real health and discovered capabilities, and ASSIGN a capability to a company/department/agent with an explicit autonomy level (read/prepare/execute/approval_required/disabled) -- these assignments are real Postgres rows (connector_capability_assignments), not a cosmetic form. Two new chat tools (list_connectors, get_connector_status) expose the same real data to WhatsApp/Admin Copilot. A real mid-build correction is recorded here honestly: the meta connector was initially mis-described as covering Instagram/Facebook social posting; investigation found that''s a real, separate, already-live system (lib/social/repositories/accounts.ts''s social_accounts table, owner_id-scoped) not safely wireable in this pass without first confirming owner_id''s relationship to tenant_id -- corrected to describe meta accurately as tracking the same WhatsApp Business Cloud API signal as whatsapp, with the Instagram/Facebook gap stated as a genuine, precisely-scoped future item.',
  'hermes',
  'Engineering',
  'list_connectors, get_connector_status',
